<label style="margin-top:6px">Revolution angle: <span id="angVal">0°</span>
  <input type="range" id="sweepAngle" min="0" max="360" step="1" value="0">
</label>

<button id="btnPlay">▶ Revolve the profile</button>

<div style="border-top:1px solid #dcdfe3;margin-top:6px;padding-top:5px;font-weight:600">Guided demo</div>
<div style="display:flex;gap:4px">
