function disposeChildren(g) {
  for (const c of g.children.slice()) {
    c.geometry?.dispose?.();
    g.remove(c);
  }
}

function buildRegion() {
  const sh = SOLIDS[curKey].shape;
  const g = new THREE.ShapeGeometry(sh);
