/* palette ----------------------------------------------------------------- */
const C_SOLID = 0x4EC5C5;
const C_EDGE = 0x00A3A8;
const C_FILL = 0xA9E2E0;

/* axis of revolution ------------------------------------------------------ */
const axisMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const axisMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 4.4, 12), axisMat);
axisMesh.rotation.z = -Math.PI / 2;
