// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ───────────────────────────────────────────────────────────
// axis of revolution      → CylinderGeometry(0.016,0.016,4.6) rot z -90°, black MeshBasic
// axis see-through ghost  → CylinderGeometry(0.013,...) depthTest:false renderOrder 12, #4a4a4a
// rotation arrow          → TubeGeometry(CatmullRom arc r=0.35, 300°, YZ plane @x=2.05) black
// arrowhead               → ConeGeometry(0.055,0.17) along arc tangent, black
// generating region fill  → ShapeGeometry (XY plane) MeshBasic #A9E2E0 opacity .7 DoubleSide
// generating region edge  → LineLoop of shape points, #00A3A8
// start cap (theta=0)     → second Mesh/LineLoop sharing the region geometry
// solid of revolution     → LatheGeometry(profile, seg, phiStart=-90°, phiLength=sweep)
//                           MeshPhysicalMaterial pale aqua #8ED9D9, DoubleSide (tube opacity .55)
// silhouette end circles  → Line arcs (#00A3A8) at extreme axial profile points
// framing box (invisible) → BoxGeometry(5.0,4.6,2.8) so camera fit is stable
// title / axis label / caption box / panel letter / angle readout → addLabel HTML
// ───────────────────────────────────────────────────────────────────────────

const figRoot = new THREE.Group();
scene.add(figRoot);

/* lights: soft airbrushed pale-aqua shading with an upper-left highlight band */
scene.add(new THREE.HemisphereLight(0xffffff, 0xa8e2e2, 0.95));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.05);
keyLight.position.set(-2.6, 3.2, 4.2);
scene.add(keyLight);
const rimLight = new THREE.DirectionalLight(0xffffff, 0.45);
rimLight.position.set(2.8, 1.4, 2.4);
scene.add(rimLight);
const fillLight = new THREE.DirectionalLight(0xd6f4f2, 0.3);
fillLight.position.set(1.5, -2.5, -3);
scene.add(fillLight);

/* palette ----------------------------------------------------------------- */
const C_SOLID = 0x8ED9D9;   // pale aqua body (light picks out #DFF3F0 highlight)
const C_EDGE = 0x00A3A8;   // silhouette / outline
const C_FILL = 0xA9E2E0;   // flat region fill

/* axis of revolution ------------------------------------------------------ */
const axisMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const axisMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 4.6, 14), axisMat);
axisMesh.rotation.z = -Math.PI / 2;
figRoot.add(axisMesh);

// The part of the axis hidden inside the solid: always drawn on top, thin & grey,
// exactly like the faint through-line in the printed figure.
const ghostMat = new THREE.MeshBasicMaterial({
  color: 0x4a4a4a, depthTest: false, depthWrite: false, transparent: true, opacity: 0.95
});
const axisGhost = new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.013, 4.6, 10), ghostMat);
axisGhost.rotation.z = -Math.PI / 2;
axisGhost.renderOrder = 12;
figRoot.add(axisGhost);

/* rotation-direction arrow (YZ plane at x = 2.05) ------------------------- */
(function buildArrow() {
  const R = 0.35, X = 2.05;
  const a0 = THREE.MathUtils.degToRad(30), a1 = THREE.MathUtils.degToRad(330);
  const pts = [];
  for (let i = 0; i <= 48; i++) {
    const t = a0 + (a1 - a0) * (i / 48);
    pts.push(new THREE.Vector3(X, R * Math.cos(t), R * Math.sin(t)));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 64, 0.014, 8, false),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  figRoot.add(tube);

  const tip = pts[pts.length - 1];
  const tan = new THREE.Vector3(0, -Math.sin(a1), Math.cos(a1)).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.17, 14),
    new THREE.MeshBasicMaterial({ color: 0x000000 }));
  head.position.copy(tip).addScaledVector(tan, 0.06);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  figRoot.add(head);
})();

/* solid definitions -------------------------------------------------------- */
function rectShape(x0, x1, y0, y1) {
  const s = new THREE.Shape();
  s.moveTo(x0, y0); s.lineTo(x1, y0); s.lineTo(x1, y1); s.lineTo(x0, y1); s.closePath();
  return s;
}
function semiShape(r) {
  const s = new THREE.Shape();
  s.moveTo(-r, 0);
  s.absarc(0, 0, r, Math.PI, 0, true);
  s.closePath();
  return s;
}
function triShape() {
  const s = new THREE.Shape();
  s.moveTo(-1.5, 0); s.lineTo(1.5, 0); s.lineTo(1.5, 1.2); s.closePath();
  return s;
}
function semiProfile(r) {
  const p = [];
  for (let i = 0; i <= 48; i++) {
    const t = Math.PI * i / 48;
    p.push(new THREE.Vector2(r * Math.sin(t), -r * Math.cos(t)));
  }
  return p;
}
const V2 = (r, x) => new THREE.Vector2(r, x);   // (radius, axial position = world x)

const SOLIDS = {
  cyl: {
    caption: 'Right circular cylinder', letter: '(a)',
    profile: [V2(0, -1.5), V2(1.0, -1.5), V2(1.0, 1.5), V2(0, 1.5)],
    shape: rectShape(-1.5, 1.5, 0, 1.0), ghost: false,
    body: 'A rectangle of height 1 and length 3 revolved about its lower edge sweeps out a right circular cylinder of radius 1 and length 3.'
  },
  sph: {
    caption: 'Solid sphere', letter: '(b)',
    profile: semiProfile(1.2),
    shape: semiShape(1.2), ghost: false,
    body: 'A semicircular region of radius 1.2 whose diameter lies on the axis sweeps out a solid sphere of radius 1.2.'
  },
  cone: {
    caption: 'Solid cone', letter: '(c)',
    profile: [V2(0, -1.5), V2(1.2, 1.5), V2(0, 1.5)],
    shape: triShape(), ghost: false,
    body: 'A right triangle with its apex on the axis at x = -1.5 and a vertical leg of height 1.2 at x = 1.5 sweeps out a solid cone that points left and widens to the right.'
  },
  tube: {
    caption: 'Hollowed right circular cylinder', letter: '(d)',
    profile: [V2(0.5, -1.5), V2(1.1, -1.5), V2(1.1, 1.5), V2(0.5, 1.5), V2(0.5, -1.5)],
    shape: rectShape(-1.5, 1.5, 0.5, 1.1), ghost: true,
    body: 'The rectangle is lifted off the axis, so the gap of radius 0.5 is never filled: the solid is a tube with annular end faces (inner radius 0.5, outer radius 1.1).'
  }
};

/* materials --------------------------------------------------------------- */
const solidMat = new THREE.MeshPhysicalMaterial({
  color: C_SOLID, roughness: 0.26, metalness: 0.0,
  clearcoat: 0.65, clearcoatRoughness: 0.3,
  side: THREE.DoubleSide, transparent: true, opacity: 1
});
const regionMat = new THREE.MeshBasicMaterial({
  color: C_FILL, side: THREE.DoubleSide, transparent: true, opacity: 0.7, depthWrite: false
});
const edgeMat = new THREE.LineBasicMaterial({ color: C_EDGE, transparent: true, opacity: 1 });

/* solid + region objects --------------------------------------------------- */
const latheHolder = new THREE.Group();
latheHolder.rotation.z = -Math.PI / 2;           // lathe +Y axis → world +X
figRoot.add(latheHolder);
const latheMesh = new THREE.Mesh(new THREE.BufferGeometry(), solidMat);
latheHolder.add(latheMesh);

const arcGroup = new THREE.Group();
figRoot.add(arcGroup);

const regionPivot = new THREE.Group();          // rotates about world X by sweep
const regionMesh = new THREE.Mesh(new THREE.BufferGeometry(), regionMat);
const regionEdge = new THREE.LineLoop(new THREE.BufferGeometry(), edgeMat);
regionMesh.renderOrder = 4; regionEdge.renderOrder = 5;
regionPivot.add(regionMesh, regionEdge);
figRoot.add(regionPivot);

const startMesh = new THREE.Mesh(new THREE.BufferGeometry(), regionMat);
const startEdge = new THREE.LineLoop(new THREE.BufferGeometry(), edgeMat);
startMesh.renderOrder = 4; startEdge.renderOrder = 5;
figRoot.add(startMesh, startEdge);

/* invisible framing box so the camera fit is stable across solids ---------- */
const frameBox = new THREE.Mesh(new THREE.BoxGeometry(5.0, 4.6, 2.8),
  new THREE.MeshBasicMaterial({ visible: false }));
frameBox.visible = false;
figRoot.add(frameBox);

/* state ------------------------------------------------------------------- */
let curKey = 'cyl';
let sweepDeg = 0;
let fade = 1, pendingKey = null;
let seeThrough = false;

function baseOpacity() {
  if (SOLIDS[curKey].ghost) return 0.55;
  return seeThrough ? 0.48 : 1.0;
}

function disposeChildren(g) {
  for (const c of g.children.slice()) {
    c.geometry?.dispose?.();
    g.remove(c);
  }
}

function buildRegion() {
  const sh = SOLIDS[curKey].shape;
  const g = new THREE.ShapeGeometry(sh);
  const pts = sh.getPoints(72).map(p => new THREE.Vector3(p.x, p.y, 0));
  const eg = new THREE.BufferGeometry().setFromPoints(pts);
  regionMesh.geometry.dispose(); regionMesh.geometry = g;
  startMesh.geometry = g;
  regionEdge.geometry.dispose(); regionEdge.geometry = eg;
  startEdge.geometry = eg;
}

function buildSwept() {
  const S = SOLIDS[curKey];
  const rad = THREE.MathUtils.degToRad(sweepDeg);
  const show = sweepDeg > 1.5;
  latheMesh.visible = show;
  if (show) {
    const seg = Math.max(4, Math.ceil(140 * sweepDeg / 360));
    const g = new THREE.LatheGeometry(S.profile, seg, -Math.PI / 2, rad);
    latheMesh.geometry.dispose();
    latheMesh.geometry = g;
  }
  // silhouette arcs at the extreme axial positions
  disposeChildren(arcGroup);
  if (show) {
    let xMin = Infinity, xMax = -Infinity;
    S.profile.forEach(p => { xMin = Math.min(xMin, p.y); xMax = Math.max(xMax, p.y); });
    const seen = new Set();
    S.profile.forEach(p => {
      if (p.x < 0.01) return;
      if (Math.abs(p.y - xMin) > 1e-6 && Math.abs(p.y - xMax) > 1e-6) return;
      const k = p.x.toFixed(3) + '@' + p.y.toFixed(3);
      if (seen.has(k)) return; seen.add(k);
      const n = Math.max(6, Math.ceil(110 * sweepDeg / 360));
      const pts = [];
      for (let i = 0; i <= n; i++) {
        const t = rad * i / n;
        pts.push(new THREE.Vector3(p.y, p.x * Math.cos(t), p.x * Math.sin(t)));
      }
      arcGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), edgeMat));
    });
  }
  regionPivot.rotation.x = rad;
  const showStart = sweepDeg > 2 && sweepDeg < 358;
  startMesh.visible = showStart; startEdge.visible = showStart;
}

/* labels ------------------------------------------------------------------ */
const titleLbl = addLabel('Some Familiar Solids of Revolution', new THREE.Vector3(0, 2.1, 0),
  { color: '#333333', fontSize: '21px' });

const axisLbl = addLabel('Axis of revolution', new THREE.Vector3(-2.3, -0.38, 0),
  { color: '#111111', fontSize: '15px' });
axisLbl.div.style.textShadow = '0 0 4px #fff, 0 0 4px #fff';

const capLbl = addLabel(SOLIDS[curKey].caption, new THREE.Vector3(0, -1.78, 0),
  { color: '#111111', fontSize: '16px', background: '#ffffff' });
capLbl.div.style.border = '1px solid #8A8A8A';
capLbl.div.style.padding = '4px 14px';
capLbl.div.style.borderRadius = '2px';

const letLbl = addLabel('<i>' + SOLIDS[curKey].letter + '</i>', new THREE.Vector3(0, -2.2, 0),
  { color: '#111111', fontSize: '19px' });
letLbl.div.style.fontFamily = 'Georgia, "Times New Roman", serif';

const angLbl = addLabel('', new THREE.Vector3(2.05, 0.66, 0.0),
  { color: '#00787c', fontSize: '13px', background: 'rgba(255,255,255,0.85)' });

/* interactivity ----------------------------------------------------------- */
registerInteractive(latheMesh, {
  title: 'Solid of revolution',
  tooltip: 'The swept solid',
  body: SOLIDS[curKey].body
});
registerInteractive(regionMesh, {
  title: 'Generating plane region',
  tooltip: 'The flat region being revolved',
  body: 'This flat region lies in a plane through the axis. Every position of it during the turn is a cross-section of the solid; the solid is the union of all rotated copies.'
});

/* apply solid ------------------------------------------------------------- */
function applySolid() {
  const S = SOLIDS[curKey];
  solidMat.opacity = baseOpacity();
  solidMat.depthWrite = baseOpacity() >= 0.99;
  latheMesh.renderOrder = baseOpacity() >= 0.99 ? 0 : 2;
  buildRegion();
  buildSwept();
  capLbl.div.innerHTML = S.caption;
  letLbl.div.innerHTML = '<i>' + S.letter + '</i>';
  const e = _interactiveObjects.find(o => o.object === latheMesh);
  if (e) e.info.body = S.body;
  document.querySelectorAll('#ui button[data-sol]').forEach(b =>
    b.classList.toggle('active', b.dataset.sol === curKey));
}

function setSweep(deg) {
  sweepDeg = Math.max(0, Math.min(360, deg));
  buildSwept();
  const slider = document.getElementById('sweepAngle');
  if (slider) slider.value = Math.round(sweepDeg);
  document.getElementById('angVal').textContent = Math.round(sweepDeg) + '°';
  angLbl.div.innerHTML = Math.round(sweepDeg) + '°';
}

applySolid();
setSweep(0);

/* camera ------------------------------------------------------------------ */
setCameraView({ projection: 'perspective', azimuthDeg: 25, elevationDeg: 15, rollDeg: 0, heightFraction: 0.68 });
controls.minPolarAngle = 0.18;
controls.maxPolarAngle = Math.PI - 0.18;
controls.enableDamping = true;
document.getElementById('btnReset').style.display = '';

/* ── controls ─────────────────────────────────────────────────────────────── */
const btnMap = { solCyl: 'cyl', solSph: 'sph', solCone: 'cone', solTube: 'tube' };
Object.keys(btnMap).forEach(id => {
  const b = document.getElementById(id);
  b.dataset.sol = btnMap[id];
  b.addEventListener('click', () => requestSolid(btnMap[id]));
});

function requestSolid(k) {
  if (k === curKey || pendingKey === k) return;
  pendingKey = k;
}

document.getElementById('sweepAngle').addEventListener('input', (e) => {
  tween = null; playing = false; updatePlayBtn();
  setSweep(parseFloat(e.target.value));
});

document.getElementById('seeThru').addEventListener('change', (e) => {
  seeThrough = e.target.checked;
  solidMat.depthWrite = baseOpacity() >= 0.99;
  latheMesh.renderOrder = baseOpacity() >= 0.99 ? 0 : 2;
});

let playing = false;
const playBtn = document.getElementById('btnPlay');
function updatePlayBtn() {
  playBtn.textContent = playing ? '❚❚ Pause revolve' : '▶ Revolve the profile';
  playBtn.classList.toggle('active', playing);
}
playBtn.addEventListener('click', () => {
  playing = !playing;
  if (playing) tween = null;
  updatePlayBtn();
});

/* demo steps -------------------------------------------------------------- */
const STEPS = [
  { t: 'The flat region', n: 'A rectangle rests with one edge on the axis of revolution. Nothing has been revolved yet — this is the generating plane region.', k: 'cyl', a: 0 },
  { t: 'Half a turn', n: 'Sweeping the rectangle 180° traces a half-cylinder shell; the open edge shows the region is being dragged around the axis.', k: 'cyl', a: 180 },
  { t: 'Full cylinder', n: 'A full 360° sweep closes the surface: the rectangle generates a right circular cylinder with radius equal to the rectangle\'s height.', k: 'cyl', a: 360 },
  { t: 'Semicircle → sphere', n: 'Replace the rectangle with a semicircle whose diameter lies on the axis. Revolving it gives the solid sphere of the same radius.', k: 'sph', a: 360 },
  { t: 'Triangle → cone', n: 'A right triangle with its apex on the axis sweeps into a solid cone; the slanted hypotenuse becomes the lateral surface.', k: 'cone', a: 360 },
  { t: 'Offset rectangle → hollow cylinder', n: 'Lift the rectangle off the axis and the gap never gets filled: the result is a hollowed right circular cylinder with annular ends.', k: 'tube', a: 360 }
];
let stepIdx = 0;
let tween = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  playing = false; updatePlayBtn();
  requestSolid(s.k);
  tween = { from: sweepDeg, to: s.a, t: 0, dur: 1.0 };
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.t;
  document.getElementById('stepText').textContent = s.n;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── update loop (independent of the scaffold's render loop) ──────────────── */
let _last = performance.now();
let _intro = 0.45;
function figTick(now) {
  requestAnimationFrame(figTick);
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  // cross-fade on panel switch
  if (pendingKey) {
    fade -= dt * 4;
    if (fade <= 0) { fade = 0; curKey = pendingKey; pendingKey = null; applySolid(); }
  } else if (fade < 1) {
    fade = Math.min(1, fade + dt * 4);
  }
  const base = baseOpacity();
  solidMat.opacity = base * fade;
  solidMat.depthWrite = (base * fade) >= 0.99;
  regionMat.opacity = 0.7 * fade;
  edgeMat.opacity = fade;

  // intro reveal so the first view shows the finished solid
  if (_intro > 0) {
    _intro -= dt;
    if (_intro <= 0) { tween = { from: 0, to: 360, t: 0, dur: 1.3 }; }
  }

  if (tween) {
    tween.t += dt;
    const u = Math.min(1, tween.t / tween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    setSweep(tween.from + (tween.to - tween.from) * e);
    if (u >= 1) tween = null;
  } else if (playing) {
    let a = sweepDeg + dt * 95;
    if (a >= 360) a -= 360;
    setSweep(a);
  }
}
requestAnimationFrame(figTick);
// @FIGURE_CODE_END

