<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ───────────────────────────────────────────────────────────
// top axis line        → CylinderGeometry(0.02,0.02,4.5) rot z -90°, black MeshBasic
// top region fill      → ShapeGeometry(profile polygon, XY plane) MeshBasic #CFEFEC
// top region stroke    → offset-polygon ribbon mesh, MeshBasic #00A3A8 (thick outline)
// rotation arrow       → TubeGeometry(circle arc r=0.42 in YZ plane @x=1.95) black
// arrowhead            → ConeGeometry(0.06,0.18) along arc tangent, black
// bottom axis line     → CylinderGeometry(0.022,0.022,4.15) rot z -90°, black  (stubs protrude 0.57)
// axis ghost in solid  → CylinderGeometry(0.014,0.014,3.0) depthTest:false, #555
// solid of revolution  → LatheGeometry(profile, seg, phiStart=-90°, phiLength=sweep)
//                        ShaderMaterial: pale aqua #9FE0DE body, #F4FDFC specular band,
//                        #35B5B2 silhouette darkening, DoubleSide
// end silhouettes      → TubeGeometry circles r=profile extremes, #00A3A8
// sweeping region      → ShapeGeometry copy on pivot rotating about world X (faint)
// framing box          → invisible BoxGeometry(4.7,6.0,2.8) so camera fit is stable
// title / axis label / caption box / panel letter / angle readout → addLabel HTML
// ───────────────────────────────────────────────────────────────────────────

const figRoot = new THREE.Group();
scene.add(figRoot);

const topGroup = new THREE.Group();
topGroup.position.y = 1.68;
topGroup.scale.setScalar(0.72);
figRoot.add(topGroup);

const botGroup = new THREE.Group();
botGroup.position.y = -0.55;
figRoot.add(botGroup);

/* palette ----------------------------------------------------------------- */
const C_EDGE = 0x00A3A8;
const C_FILL_TOP = 0xCFEFEC;

/* materials --------------------------------------------------------------- */
const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });

const solidMat = new THREE.ShaderMaterial({
  uniforms: {
    uHi: { value: new THREE.Color(0xF6FEFD) },
    uMid: { value: new THREE.Color(0x9FE0DE) },
    uLo: { value: new THREE.Color(0x35B5B2) },
    uOpacity: { value: 1.0 },
    uLight: { value: new THREE.Vector3(-0.42, 0.72, 0.55).normalize() }
  },
  vertexShader: `
    varying vec3 vN; varying vec3 vP;
    void main(){
      vec4 mv = modelViewMatrix * vec4(position, 1.0);
      vN = normalize(normalMatrix * normal);
      vP = mv.xyz;
      gl_Position = projectionMatrix * mv;
    }`,
  fragmentShader: `
    uniform vec3 uHi; uniform vec3 uMid; uniform vec3 uLo; uniform vec3 uLight;
    uniform float uOpacity;
    varying vec3 vN; varying vec3 vP;
    void main(){
      vec3 N = normalize(vN);
      vec3 V = normalize(-vP);
      float f = abs(dot(N, V));                 // 1 = facing viewer, 0 = silhouette
      float d = clamp(abs(dot(N, normalize(uLight))), 0.0, 1.0);
      vec3 col = mix(uLo, uMid, smoothstep(0.0, 0.60, f));
      float band = pow(d, 2.0);                  // broad airbrushed specular band
      col = mix(col, uHi, 0.85 * band * smoothstep(0.02, 0.55, f));
      gl_FragColor = vec4(col, uOpacity);
    }`,
  side: THREE.DoubleSide,
  transparent: true
});

const topFillMat = new THREE.MeshBasicMaterial({
  color: C_FILL_TOP, side: THREE.DoubleSide, transparent: true, opacity: 1.0
});
const topStrokeMat = new THREE.MeshBasicMaterial({
  color: C_EDGE, side: THREE.DoubleSide, transparent: true, opacity: 1.0
});
const botFillMat = new THREE.MeshBasicMaterial({
  color: C_FILL_TOP, side: THREE.DoubleSide, transparent: true, opacity: 0.55, depthWrite: false
});
const botStrokeMat = new THREE.MeshBasicMaterial({
  color: C_EDGE, side: THREE.DoubleSide, transparent: true, opacity: 0.85, depthWrite: false
});
const outlineMat = new THREE.MeshBasicMaterial({ color: C_EDGE, transparent: true, opacity: 1.0 });
const ghostMat = new THREE.MeshBasicMaterial({
  color: 0x555555, depthTest: false, depthWrite: false, transparent: true, opacity: 0.9
});

/* axes -------------------------------------------------------------------- */
const topAxis = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 4.5, 14), blackMat);
topAxis.rotation.z = -Math.PI / 2;
topGroup.add(topAxis);

const botAxis = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 4.15, 14), blackMat);
botAxis.rotation.z = -Math.PI / 2;
botGroup.add(botAxis);

const axisGhost = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 3.02, 10), ghostMat);
axisGhost.rotation.z = -Math.PI / 2;
axisGhost.renderOrder = 14;
botGroup.add(axisGhost);

/* rotation-direction arrow (top tier, YZ plane at x = 1.95) --------------- */
(function buildArrow() {
  const R = 0.42, X = 1.95;
  const a0 = THREE.MathUtils.degToRad(25), a1 = THREE.MathUtils.degToRad(335);
  const pts = [];
  for (let i = 0; i <= 56; i++) {
    const t = a0 + (a1 - a0) * (i / 56);
    pts.push(new THREE.Vector3(X, R * Math.cos(t), R * Math.sin(t)));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  topGroup.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 72, 0.022, 8, false), blackMat));

  const tip = pts[pts.length - 1];
  const tan = new THREE.Vector3(0, -Math.sin(a1), Math.cos(a1)).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.22, 14), blackMat);
  head.position.copy(tip).addScaledVector(tan, 0.08);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  topGroup.add(head);
})();

/* profiles ---------------------------------------------------------------- */
const V2 = (r, x) => new THREE.Vector2(r, x);   // (radius, axial position = world x)
function semiProfile(r) {
  const p = [];
  for (let i = 0; i <= 48; i++) {
    const t = Math.PI * i / 48;
    p.push(new THREE.Vector2(r * Math.sin(t), -r * Math.cos(t)));
  }
  return p;
}

const SOLIDS = {
  cyl: {
    caption: 'Right circular cylinder', letter: '(a)',
    profile: [V2(0, -1.5), V2(1.0, -1.5), V2(1.0, 1.5), V2(0, 1.5)],
    body: 'A rectangle of height 1 and length 3 with its lower edge on the axis sweeps out a right circular cylinder of radius 1 and length 3.'
  },
  sph: {
    caption: 'Solid sphere', letter: '(b)',
    profile: semiProfile(1.2),
    body: 'A semicircular region of radius 1.2 whose diameter lies on the axis sweeps out a solid sphere of radius 1.2.'
  },
  cone: {
    caption: 'Solid cone', letter: '(c)',
    profile: [V2(0, -1.5), V2(1.2, 1.5), V2(0, 1.5)],
    body: 'A right triangle with its apex on the axis at the left and a vertical leg of height 1.2 at the right sweeps out a solid cone that points left and widens to the right.'
  },
  tube: {
    caption: 'Hollowed right<br>circular cylinder', letter: '(d)',
    profile: [V2(0.5, -1.5), V2(1.1, -1.5), V2(1.1, 1.5), V2(0.5, 1.5), V2(0.5, -1.5)],
    translucent: true,
    body: 'The rectangle is lifted off the axis, so the gap of radius 0.5 is never filled: the solid is a tube with annular end faces (inner radius 0.5, outer radius 1.1).'
  }
};

/* profile (radius, axial) → flat polygon in the XY plane ------------------ */
function profilePolygon(profile) {
  const out = [];
  for (const p of profile) {
    const v = new THREE.Vector2(p.y, p.x);          // x = axial, y = radius
    const last = out[out.length - 1];
    if (last && Math.abs(last.x - v.x) < 1e-6 && Math.abs(last.y - v.y) < 1e-6) continue;
    out.push(v);
  }
  if (out.length > 1) {
    const a = out[0], b = out[out.length - 1];
    if (Math.abs(a.x - b.x) < 1e-6 && Math.abs(a.y - b.y) < 1e-6) out.pop();
  }
  return out;
}

function polygonFill(pts) {
  const sh = new THREE.Shape();
  sh.moveTo(pts[0].x, pts[0].y);
  for (let i = 1; i < pts.length; i++) sh.lineTo(pts[i].x, pts[i].y);
  sh.closePath();
  return new THREE.ShapeGeometry(sh);
}

/* thick outward outline ribbon for a closed polygon ----------------------- */
function polygonOutline(pts, w) {
  const n = pts.length;
  let A = 0;
  for (let i = 0; i < n; i++) {
    const a = pts[i], b = pts[(i + 1) % n];
    A += a.x * b.y - b.x * a.y;
  }
  const ccw = A > 0;
  const nrm = [];
  for (let i = 0; i < n; i++) {
    const prev = pts[(i - 1 + n) % n], cur = pts[i], next = pts[(i + 1) % n];
    const e1 = new THREE.Vector2(cur.x - prev.x, cur.y - prev.y);
    const e2 = new THREE.Vector2(next.x - cur.x, next.y - cur.y);
    if (e1.length() < 1e-9) e1.copy(e2);
    if (e2.length() < 1e-9) e2.copy(e1);
    e1.normalize(); e2.normalize();
    const n1 = ccw ? new THREE.Vector2(e1.y, -e1.x) : new THREE.Vector2(-e1.y, e1.x);
    const n2 = ccw ? new THREE.Vector2(e2.y, -e2.x) : new THREE.Vector2(-e2.y, e2.x);
    const s = n1.clone().add(n2);
    if (s.length() < 1e-6) s.copy(n2);
    nrm.push(s.normalize());
  }
  const verts = [];
  for (let i = 0; i < n; i++) {
    const a = pts[i], b = pts[(i + 1) % n];
    const na = nrm[i], nb = nrm[(i + 1) % n];
    const ax = a.x + na.x * w, ay = a.y + na.y * w;
    const bx = b.x + nb.x * w, by = b.y + nb.y * w;
    verts.push(a.x, a.y, 0, b.x, b.y, 0, bx, by, 0);
    verts.push(a.x, a.y, 0, bx, by, 0, ax, ay, 0);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  return g;
}

/* region meshes ----------------------------------------------------------- */
const topFill = new THREE.Mesh(new THREE.BufferGeometry(), topFillMat);
const topStroke = new THREE.Mesh(new THREE.BufferGeometry(), topStrokeMat);
topGroup.add(topFill, topStroke);

const regionPivot = new THREE.Group();                 // rotates about world X
const botFill = new THREE.Mesh(new THREE.BufferGeometry(), botFillMat);
const botStroke = new THREE.Mesh(new THREE.BufferGeometry(), botStrokeMat);
botFill.renderOrder = 4; botStroke.renderOrder = 5;
regionPivot.add(botFill, botStroke);
botGroup.add(regionPivot);

const startFill = new THREE.Mesh(new THREE.BufferGeometry(), botFillMat);
const startStroke = new THREE.Mesh(new THREE.BufferGeometry(), botStrokeMat);
startFill.renderOrder = 4; startStroke.renderOrder = 5;
botGroup.add(startFill, startStroke);

/* solid ------------------------------------------------------------------- */
const latheHolder = new THREE.Group();
latheHolder.rotation.z = -Math.PI / 2;                 // lathe +Y → world +X
botGroup.add(latheHolder);
const latheMesh = new THREE.Mesh(new THREE.BufferGeometry(), solidMat);
latheHolder.add(latheMesh);

const outlineGroup = new THREE.Group();
botGroup.add(outlineGroup);

/* invisible framing box so the camera fit is stable across solids --------- */
const frameBox = new THREE.Mesh(new THREE.BoxGeometry(4.7, 6.0, 2.8),
  new THREE.MeshBasicMaterial({ visible: false }));
frameBox.position.y = 0.15;
frameBox.visible = false;
figRoot.add(frameBox);

/* state ------------------------------------------------------------------- */
let curKey = 'cyl';
let sweepDeg = 360;
let fade = 1, pendingKey = null;
let seeThrough = false;

function baseOpacity() {
  if (SOLIDS[curKey].translucent) return 0.6;
  return seeThrough ? 0.48 : 1.0;
}

function disposeChildren(g) {
  for (const c of g.children.slice()) { c.geometry?.dispose?.(); g.remove(c); }
}

function buildRegions() {
  const poly = profilePolygon(SOLIDS[curKey].profile);
  const fillG = polygonFill(poly);
  const strokeG = polygonOutline(poly, 0.03);

  topFill.geometry.dispose(); topFill.geometry = fillG;
  topStroke.geometry.dispose(); topStroke.geometry = strokeG;

  const fillG2 = fillG.clone();
  const strokeG2 = strokeG.clone();
  botFill.geometry.dispose(); botFill.geometry = fillG2;
  botStroke.geometry.dispose(); botStroke.geometry = strokeG2;
  startFill.geometry = fillG2;
  startStroke.geometry = strokeG2;
}

function buildSwept() {
  const S = SOLIDS[curKey];
  const rad = THREE.MathUtils.degToRad(sweepDeg);
  const show = sweepDeg > 1.5;
  latheMesh.visible = show;
  if (show) {
    const seg = Math.max(4, Math.ceil(150 * sweepDeg / 360));
    const g = new THREE.LatheGeometry(S.profile, seg, -Math.PI / 2, rad);
    latheMesh.geometry.dispose();
    latheMesh.geometry = g;
  }

  // thin teal silhouette circles at the extreme axial profile positions
  disposeChildren(outlineGroup);
  if (show) {
    let xMin = Infinity, xMax = -Infinity;
    S.profile.forEach(p => { xMin = Math.min(xMin, p.y); xMax = Math.max(xMax, p.y); });
    const seen = new Set();
    S.profile.forEach(p => {
      if (p.x < 0.04) return;
      if (Math.abs(p.y - xMin) > 1e-6 && Math.abs(p.y - xMax) > 1e-6) return;
      const k = p.x.toFixed(3) + '@' + p.y.toFixed(3);
      if (seen.has(k)) return; seen.add(k);
      const n = Math.max(8, Math.ceil(90 * sweepDeg / 360));
      const pts = [];
      for (let i = 0; i <= n; i++) {
        const t = -Math.PI / 2 + rad * i / n;
        pts.push(new THREE.Vector3(p.y, -p.x * Math.sin(t), p.x * Math.cos(t)));
      }
      const curve = new THREE.CatmullRomCurve3(pts);
      outlineGroup.add(new THREE.Mesh(
        new THREE.TubeGeometry(curve, Math.max(12, n), 0.011, 6, false), outlineMat));
    });
  }

  regionPivot.rotation.x = rad;
  const showMoving = sweepDeg < 358;
  botFill.visible = showMoving; botStroke.visible = showMoving;
  const showStart = sweepDeg > 2;
  startFill.visible = showStart; startStroke.visible = showStart;
}

/* labels ------------------------------------------------------------------ */
const titleLbl = addLabel('Some Familiar Solids of Revolution', new THREE.Vector3(0, 3.02, 0),
  { color: '#222222', fontSize: '26px' });
titleLbl.div.style.fontFamily = 'Helvetica, Arial, sans-serif';

const axisLbl = addLabel('Axis of revolution', new THREE.Vector3(-1.95, -0.55, 0),
  { color: '#111111', fontSize: '19px', offset: [4, 26] });
axisLbl.div.style.textShadow = '0 0 5px #fff, 0 0 5px #fff, 0 0 5px #fff';
axisLbl.div.style.fontFamily = 'Helvetica, Arial, sans-serif';

const capLbl = addLabel(SOLIDS[curKey].caption, new THREE.Vector3(0, -2.22, 0),
  { color: '#111111', fontSize: '20px', background: '#ffffff' });
capLbl.div.style.border = '1px solid #8A8A8A';
capLbl.div.style.padding = '5px 16px';
capLbl.div.style.borderRadius = '2px';
capLbl.div.style.textAlign = 'center';
capLbl.div.style.lineHeight = '1.2';
capLbl.div.style.fontFamily = 'Helvetica, Arial, sans-serif';

const letLbl = addLabel('<i>' + SOLIDS[curKey].letter + '</i>', new THREE.Vector3(0, -2.78, 0),
  { color: '#111111', fontSize: '25px' });
letLbl.div.style.fontFamily = 'Georgia, "Times New Roman", serif';

const angLbl = addLabel('', new THREE.Vector3(1.4, 2.12, 0.25),
  { color: '#00787c', fontSize: '15px', background: 'rgba(255,255,255,0.9)' });

/* interactivity ----------------------------------------------------------- */
registerInteractive(latheMesh, {
  title: 'Solid of revolution',
  tooltip: 'The swept solid',
  body: SOLIDS[curKey].body
});
registerInteractive(topFill, {
  title: 'Generating plane region',
  tooltip: 'The flat region that is revolved',
  body: 'This flat region lies in a plane through the axis of revolution. Each rotated copy of it is a cross-section of the solid; the solid is the union of all of those copies as the region turns a full 360°.'
});
registerInteractive(botFill, {
  title: 'The region mid-sweep',
  tooltip: 'The region part-way around',
  body: 'The same region, now carried part of the way around the axis. The surface it has traced so far is the boundary of the growing solid.'
});

/* apply solid ------------------------------------------------------------- */
function applySolid() {
  const S = SOLIDS[curKey];
  buildRegions();
  buildSwept();
  capLbl.div.innerHTML = S.caption;
  letLbl.div.innerHTML = '<i>' + S.letter + '</i>';
  const e = _interactiveObjects.find(o => o.object === latheMesh);
  if (e) e.info.body = S.body;
  document.querySelectorAll('#ui button[data-sol]').forEach(b =>
    b.classList.toggle('active', b.dataset.sol === curKey));
}

function setSweep(deg) {
  sweepDeg = Math.max(0, Math.min(360, deg));
  buildSwept();
  const slider = document.getElementById('sweepAngle');
  if (slider) slider.value = Math.round(sweepDeg);
  document.getElementById('angVal').textContent = Math.round(sweepDeg) + '°';
  angLbl.div.innerHTML = Math.round(sweepDeg) + '°';
}

applySolid();
setSweep(360);

/* camera: flat, near head-on so the axis reads horizontally --------------- */
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 70, elevationDeg: 8,
  heightFraction: 0.86,
  target: [0, 0.15, 0]
});
controls.minPolarAngle = 0.15;
controls.maxPolarAngle = Math.PI - 0.15;
document.getElementById('btnReset').style.display = '';

/* ── controls ─────────────────────────────────────────────────────────────── */
const btnMap = { solCyl: 'cyl', solSph: 'sph', solCone: 'cone', solTube: 'tube' };
Object.keys(btnMap).forEach(id => {
  const b = document.getElementById(id);
  b.dataset.sol = btnMap[id];
  b.addEventListener('click', () => requestSolid(btnMap[id]));
});

function requestSolid(k) {
  if (k === curKey || pendingKey === k) return;
  pendingKey = k;
}

document.getElementById('sweepAngle').addEventListener('input', (e) => {
  tween = null; playing = false; updatePlayBtn();
  setSweep(parseFloat(e.target.value));
});

document.getElementById('seeThru').addEventListener('change', (e) => {
  seeThrough = e.target.checked;
});

let playing = false;
const playBtn = document.getElementById('btnPlay');
function updatePlayBtn() {
  playBtn.textContent = playing ? '❚❚ Pause revolve' : '▶ Revolve the profile';
  playBtn.classList.toggle('active', playing);
}
playBtn.addEventListener('click', () => {
  playing = !playing;
  if (playing) { tween = null; if (sweepDeg > 359) setSweep(0); }
  updatePlayBtn();
});

/* demo steps -------------------------------------------------------------- */
const STEPS = [
  { t: 'The flat region', n: 'A rectangle rests with one edge on the axis of revolution. Nothing has been revolved yet — this is the generating plane region.', k: 'cyl', a: 0 },
  { t: 'Half a turn', n: 'Sweeping the rectangle 180° traces a half-cylinder shell; the open edge shows the region being dragged around the axis.', k: 'cyl', a: 180 },
  { t: 'Full cylinder', n: "A full 360° sweep closes the surface: the rectangle generates a right circular cylinder whose radius equals the rectangle's height.", k: 'cyl', a: 360 },
  { t: 'Semicircle → sphere', n: 'Replace the rectangle with a semicircle whose diameter lies on the axis. Revolving it gives the solid sphere of the same radius.', k: 'sph', a: 360 },
  { t: 'Triangle → cone', n: 'A right triangle with its apex on the axis sweeps into a solid cone; the slanted hypotenuse becomes the lateral surface.', k: 'cone', a: 360 },
  { t: 'Offset rectangle → hollow cylinder', n: 'Lift the rectangle off the axis and the gap never gets filled: the result is a hollowed right circular cylinder with annular ends.', k: 'tube', a: 360 }
];
let stepIdx = 2;
let tween = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  playing = false; updatePlayBtn();
  requestSolid(s.k);
  tween = { from: sweepDeg, to: s.a, t: 0, dur: 1.0 };
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.t;
  document.getElementById('stepText').textContent = s.n;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── update loop (independent of the scaffold's render loop) ──────────────── */
let _last = performance.now();
function figTick(now) {
  requestAnimationFrame(figTick);
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  // cross-fade on panel switch
  if (pendingKey) {
    fade -= dt * 4;
    if (fade <= 0) { fade = 0; curKey = pendingKey; pendingKey = null; applySolid(); }
  } else if (fade < 1) {
    fade = Math.min(1, fade + dt * 4);
  }
  const base = baseOpacity();
  solidMat.uniforms.uOpacity.value = base * fade;
  solidMat.depthWrite = (base * fade) >= 0.99;
  latheMesh.renderOrder = (base * fade) >= 0.99 ? 0 : 2;
  outlineMat.opacity = fade;
  topFillMat.opacity = fade;
  topStrokeMat.opacity = fade;
  botFillMat.opacity = 0.55 * fade;
  botStrokeMat.opacity = 0.85 * fade;

  if (tween) {
    tween.t += dt;
    const u = Math.min(1, tween.t / tween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    setSweep(tween.from + (tween.to - tween.from) * e);
    if (u >= 1) tween = null;
  } else if (playing) {
    let a = sweepDeg + dt * 95;
    if (a >= 360) a -= 360;
    setSweep(a);
  }
}
requestAnimationFrame(figTick);
